insert into public.ref_tables (slug, name, columns, data, source) values ('rebar-ph', 'Rebar: PH Bar Sizes (Nominal)', '[{"key":"d","label":"Ø","unit":"mm"},{"key":"area_mm2","label":"Area","unit":"mm²"},{"key":"perim_mm","label":"Perimeter","unit":"mm"},{"key":"kg_m","label":"Mass","unit":"kg/m"},{"key":"kg_6m","label":"6.0 m bar","unit":"kg"},{"key":"kg_75m","label":"7.5 m bar","unit":"kg"},{"key":"kg_9m","label":"9.0 m bar","unit":"kg"},{"key":"kg_12m","label":"12.0 m bar","unit":"kg"}]'::jsonb, '{"rows":[{"d":10,"area_mm2":78.5,"perim_mm":31.4,"kg_m":0.617,"kg_6m":3.7,"kg_75m":4.62,"kg_9m":5.55,"kg_12m":7.4},{"d":12,"area_mm2":113.1,"perim_mm":37.7,"kg_m":0.888,"kg_6m":5.33,"kg_75m":6.66,"kg_9m":7.99,"kg_12m":10.65},{"d":16,"area_mm2":201.1,"perim_mm":50.3,"kg_m":1.578,"kg_6m":9.47,"kg_75m":11.84,"kg_9m":14.21,"kg_12m":18.94},{"d":20,"area_mm2":314.2,"perim_mm":62.8,"kg_m":2.466,"kg_6m":14.8,"kg_75m":18.5,"kg_9m":22.2,"kg_12m":29.59},{"d":25,"area_mm2":490.9,"perim_mm":78.5,"kg_m":3.853,"kg_6m":23.12,"kg_75m":28.9,"kg_9m":34.68,"kg_12m":46.24},{"d":28,"area_mm2":615.8,"perim_mm":88,"kg_m":4.834,"kg_6m":29,"kg_75m":36.25,"kg_9m":43.5,"kg_12m":58},{"d":32,"area_mm2":804.2,"perim_mm":100.5,"kg_m":6.313,"kg_6m":37.88,"kg_75m":47.35,"kg_9m":56.82,"kg_12m":75.76},{"d":36,"area_mm2":1017.9,"perim_mm":113.1,"kg_m":7.99,"kg_6m":47.94,"kg_75m":59.93,"kg_9m":71.91,"kg_12m":95.88}],"verified":true}'::jsonb, 'Computed: A = πd²/4, mass = A × 7850 kg/m³ (≈ d²/162.2 kg/m). Nominal values; mill tolerances apply per PNS 49.');
insert into public.ref_tables (slug, name, columns, data, source) values ('rebar-grades-pns49', 'Rebar: PNS 49 Grades', '[{"key":"grade","label":"Grade"},{"key":"fy","label":"Min. yield","unit":"MPa"},{"key":"fy_ksi","label":"≈ Min. yield","unit":"ksi"},{"key":"astm","label":"≈ ASTM A615"},{"key":"note","label":"Note"}]'::jsonb, '{"rows":[{"grade":"230 / 230W","fy":230,"fy_ksi":33,"astm":"Gr 33 (legacy)","note":"Structural grade"},{"grade":"275 / 275W","fy":275,"fy_ksi":40,"astm":"Gr 40 [280]","note":"Intermediate grade"},{"grade":"415 / 415W","fy":415,"fy_ksi":60,"astm":"Gr 60 [420]","note":"High-tensile grade"}],"verified":false}'::jsonb, 'PNS 49:2002 grades (W = weldable). PNS 49:2020 replaced 2019/2002 with a numeric marking scheme. VERIFY the 2020 grade designations before relying on this table.');
insert into public.ref_tables (slug, name, columns, data, source) values ('unit-weights-materials', 'Material Unit Weights (Typical)', '[{"key":"material","label":"Material"},{"key":"kg_m3","label":"Density","unit":"kg/m³"},{"key":"kn_m3","label":"Unit weight","unit":"kN/m³"},{"key":"note","label":"Note"}]'::jsonb, '{"rows":[{"material":"Reinforced concrete","kg_m3":2400,"kn_m3":23.5,"note":"Common design value; check governing code table"},{"material":"Plain concrete","kg_m3":2300,"kn_m3":22.6,"note":""},{"material":"Structural steel","kg_m3":7850,"kn_m3":77,"note":""},{"material":"Water (fresh)","kg_m3":1000,"kn_m3":9.81,"note":""},{"material":"Seawater","kg_m3":1025,"kn_m3":10.05,"note":""},{"material":"Portland cement (bulk, loose)","kg_m3":1440,"kn_m3":14.1,"note":"40 kg bag ≈ 0.0278 m³"},{"material":"Sand (dry, loose)","kg_m3":1600,"kn_m3":15.7,"note":"Varies with moisture/bulking"},{"material":"Gravel / crushed stone","kg_m3":1700,"kn_m3":16.7,"note":"Varies with grading"},{"material":"Compacted soil (typical)","kg_m3":1800,"kn_m3":17.7,"note":"Use geotech report values"},{"material":"Aluminium","kg_m3":2700,"kn_m3":26.5,"note":""},{"material":"Glass","kg_m3":2500,"kn_m3":24.5,"note":""}],"verified":false}'::jsonb, 'Typical engineering densities for estimating. Design dead loads must come from the governing code (NSCP 2015 Ch. 2) or supplier data.');
insert into public.ref_tables (slug, name, columns, data, source) values ('sheet-steel-gauge', 'Sheet Steel Gauge (Manufacturers'' Standard)', '[{"key":"ga","label":"Gauge"},{"key":"in","label":"Thickness","unit":"in"},{"key":"mm","label":"Thickness","unit":"mm"}]'::jsonb, '{"rows":[{"ga":26,"in":0.0179,"mm":0.455},{"ga":24,"in":0.0239,"mm":0.607},{"ga":22,"in":0.0299,"mm":0.759},{"ga":20,"in":0.0359,"mm":0.912},{"ga":18,"in":0.0478,"mm":1.214},{"ga":16,"in":0.0598,"mm":1.519},{"ga":14,"in":0.0747,"mm":1.897},{"ga":12,"in":0.1046,"mm":2.657},{"ga":10,"in":0.1345,"mm":3.416}],"verified":true}'::jsonb, 'Manufacturers'' Standard Gauge for uncoated steel sheet. PH roofing is sold by BMT/TCT in mm: always confirm with the supplier.');
insert into public.ref_tables (slug, name, columns, data, source) values ('pipe-sizes-steel', 'Pipe Sizes: Steel (NPS / DN, Sch 40)', '[{"key":"nps","label":"NPS","unit":"in"},{"key":"dn","label":"DN"},{"key":"od_mm","label":"OD","unit":"mm"},{"key":"t40_mm","label":"Wall Sch 40","unit":"mm"},{"key":"id40_mm","label":"ID Sch 40","unit":"mm"}]'::jsonb, '{"rows":[{"nps":"1/2","dn":15,"od_mm":21.3,"t40_mm":2.77,"id40_mm":15.8},{"nps":"3/4","dn":20,"od_mm":26.7,"t40_mm":2.87,"id40_mm":21},{"nps":"1","dn":25,"od_mm":33.4,"t40_mm":3.38,"id40_mm":26.6},{"nps":"1-1/4","dn":32,"od_mm":42.2,"t40_mm":3.56,"id40_mm":35.1},{"nps":"1-1/2","dn":40,"od_mm":48.3,"t40_mm":3.68,"id40_mm":40.9},{"nps":"2","dn":50,"od_mm":60.3,"t40_mm":3.91,"id40_mm":52.5},{"nps":"2-1/2","dn":65,"od_mm":73,"t40_mm":5.16,"id40_mm":62.7},{"nps":"3","dn":80,"od_mm":88.9,"t40_mm":5.49,"id40_mm":77.9},{"nps":"4","dn":100,"od_mm":114.3,"t40_mm":6.02,"id40_mm":102.3},{"nps":"5","dn":125,"od_mm":141.3,"t40_mm":6.55,"id40_mm":128.2},{"nps":"6","dn":150,"od_mm":168.3,"t40_mm":7.11,"id40_mm":154.1},{"nps":"8","dn":200,"od_mm":219.1,"t40_mm":8.18,"id40_mm":202.7}],"verified":true}'::jsonb, 'ASME B36.10M nominal dimensions. PVC/uPVC and PPR pipe ODs differ by standard: check the manufacturer''s table.');
insert into public.releases (version, batch_name, notes_md, released_at) values ('v0.1.0','Conversions', E'- Unit converter: 12 categories, 81 units (SI, English, kgf/tf)\n- Reference tables: PH rebar sizes & masses, PNS 49 grades (verify), material unit weights, sheet gauge, steel pipe sizes\n- Conversions page with converter + table viewer\n- What\'s new banner on dashboard', now());
